<script lang="ts">
 import{onMount}from"svelte";import AppIcon from"../components/AppIcon.svelte";import WindowFrame from"../components/WindowFrame.svelte";import{applyChromeInsets,openWindow,setLauncherOpen,setNotificationCenterOpen,shellStore,minimizeAll}from"../../appshell/lib/store";import{groupTop}from"../../appshell/lib/window-tabs-core";import{spaceOf}from"../../appshell/lib/spaces-core";import type{AppDescriptor}from"../types";
 let{apps}:{apps:AppDescriptor[]}=$props();let v=$state(0);onMount(()=>{applyChromeInsets({top:0,bottom:48});const u=shellStore.subscribe(()=>v++);return()=>{u();applyChromeInsets({})}});let order=$derived((v,shellStore.getOrder()));let space=$derived((v,shellStore.getActiveSpace()));let wins=$derived(order.map(id=>shellStore.getWindow(id)).filter(w=>w&&!w.minimized&&spaceOf(w)===space&&(!w.groupId||groupTop(w.groupId)===w.id)));let taskApps=$derived(apps.filter(a=>!a.noDock).slice(0,10));const launch=(a:AppDescriptor)=>openWindow(a.id,a.title,a.defaultSize,undefined,{multi:a.multi});
</script>
<div class="shell win" data-shell="windows"><main class="desktop"><div class="icons">{#each apps.filter(a=>!a.noDock).slice(0,10) as app (app.id)}<AppIcon {app} onclick={()=>launch(app)}/>{/each}</div>{#each wins as win (win.id)}{@const app=apps.find(a=>a.id===win.app)}{#if app}<WindowFrame {win} {app} shell="windows"/>{/if}{/each}</main><footer class="taskbar"><button class="start" aria-label="Start" onclick={()=>setLauncherOpen(true)}>⊞</button>{#each taskApps as app (app.id)}<AppIcon {app} label={false} onclick={()=>launch(app)}/>{/each}<span></span><button title="Show desktop" onclick={minimizeAll}>▭</button><button aria-label="Action center" onclick={()=>setNotificationCenterOpen(true)}>◌</button><time>{new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}</time></footer></div>
<style>.shell{position:absolute;inset:0;color:white}.desktop{position:absolute;inset:0 0 48px;overflow:hidden}.icons{position:absolute;left:14px;top:14px;z-index:2;display:grid;grid-template-columns:76px;gap:13px}.taskbar{position:absolute;z-index:850;bottom:0;left:0;right:0;height:48px;display:flex;align-items:center;justify-content:center;gap:7px;padding:0 10px;background:#eef2f5df;color:#111;backdrop-filter:blur(30px);box-shadow:0 -1px #fff8}.taskbar>span{flex:1}.taskbar button{border:0;background:transparent;border-radius:6px;height:38px;min-width:38px}.taskbar button:hover{background:#0000000c}.start{font-size:22px;color:#0878d1}time{font-size:11px;white-space:nowrap}</style>
